  1→use std::fs;
  2→use std::io::{Read as _, Seek, SeekFrom, Write as _};
  3→use std::path::{Path, PathBuf};
  4→
  5→use chrono::{DateTime, Utc};
  6→use serde::{Deserialize, Serialize};
  7→
  8→use crate::error::CoreError;
  9→use crate::model::{AgentInfo, EngramId, TokenUsage};
 10→
 11→const SESSION_FILE: &str = "engram-session";
 12→
 13→/// Tracks an active recording session. Stored as JSON at `.git/engram-session`.
 14→#[derive(Debug, Clone, Serialize, Deserialize)]
 15→pub struct ActiveSession {
 16→    pub engram_id: EngramId,
 17→    pub agent: AgentInfo,
 18→    pub started_at: DateTime<Utc>,
 19→    pub commits: Vec<String>,
 20→    pub token_usage: TokenUsage,
 21→}
 22→
 23→impl ActiveSession {
 24→    /// Create a new active session.
 25→    pub fn new(engram_id: EngramId, agent: AgentInfo) -> Self {
 26→        Self {
 27→            engram_id,
 28→            agent,
 29→            started_at: Utc::now(),
 30→            commits: Vec::new(),
 31→            token_usage: TokenUsage::default(),
 32→        }
 33→    }
 34→
 35→    /// Path to the session file inside the .git directory.
 36→    fn session_path(git_dir: &Path) -> PathBuf {
 37→        git_dir.join(SESSION_FILE)
 38→    }
 39→
 40→    /// Save the session to disk with an exclusive file lock.
 41→    pub fn save(&self, git_dir: &Path) -> Result<(), CoreError> {
 42→        let path = Self::session_path(git_dir);
 43→        let json = serde_json::to_string_pretty(self)
 44→            .map_err(|e| CoreError::Config(format!("Failed to serialize session: {e}")))?;
 45→        let file = fs::OpenOptions::new()
 46→            .write(true)
 47→            .create(true)
 48→            .truncate(true)
 49→            .open(&path)?;
 50→        fs2::FileExt::lock_exclusive(&file).map_err(CoreError::Io)?;
 51→        (&file).write_all(json.as_bytes())?;
 52→        fs2::FileExt::unlock(&file).map_err(CoreError::Io)?;
 53→        Ok(())
 54→    }
 55→
 56→    /// Load an active session if one exists, using a shared file lock.
 57→    pub fn load(git_dir: &Path) -> Option<Self> {
 58→        let path = Self::session_path(git_dir);
 59→        let file = fs::OpenOptions::new().read(true).open(&path).ok()?;
 60→        fs2::FileExt::lock_shared(&file).ok()?;
 61→        let mut data = String::new();
 62→        (&file).read_to_string(&mut data).ok()?;
 63→        fs2::FileExt::unlock(&file).ok();
 64→        serde_json::from_str(&data).ok()
 65→    }
 66→
 67→    /// Remove the session file.
 68→    pub fn cleanup(git_dir: &Path) {
 69→        let path = Self::session_path(git_dir);
 70→        let _ = fs::remove_file(path);
 71→    }
 72→
 73→    /// Add a commit SHA to the session atomically with an exclusive lock.
 74→    pub fn add_commit(&mut self, sha: &str, git_dir: &Path) -> Result<(), CoreError> {
 75→        let path = Self::session_path(git_dir);
 76→        let file = fs::OpenOptions::new().read(true).write(true).open(&path)?;
 77→        fs2::FileExt::lock_exclusive(&file).map_err(CoreError::Io)?;
 78→
 79→        // Re-read under lock to get latest state
 80→        let mut data = String::new();
 81→        (&file).read_to_string(&mut data)?;
 82→        let mut current: ActiveSession = serde_json::from_str(&data)
 83→            .map_err(|e| CoreError::Config(format!("Session parse: {e}")))?;
 84→        current.commits.push(sha.to_string());
 85→
 86→        // Write back
 87→        let json = serde_json::to_string_pretty(&current)
 88→            .map_err(|e| CoreError::Config(format!("Session serialize: {e}")))?;
 89→        file.set_len(0)?;
 90→        (&file).seek(SeekFrom::Start(0))?;
 91→        (&file).write_all(json.as_bytes())?;
 92→
 93→        // Update self
 94→        self.commits = current.commits;
 95→        fs2::FileExt::unlock(&file).map_err(CoreError::Io)?;
 96→        Ok(())
 97→    }
 98→}
