+        Some(c) => c,
+        None => return,
+    };
+
+    if !config.push_on_push {
+        return;
+    }
+
+    let opts = SyncOptions::default();
+    match push_engrams(storage.repo(), "origin", &opts) {
+        Ok(result) => {
+            if result.refs_pushed > 0 {
+                eprintln!(
