  1→use engram_core::model::{DeadEnd, Decision};
  2→
  3→/// Best-effort extraction of reasoning insights from raw PTY output.
  4→///
  5→/// This is heuristic: it looks for common phrases that indicate rejected
  6→/// approaches or architectural decisions. Returns empty vecs if no patterns found.
  7→pub fn extract_insights(raw_output: &[u8]) -> ExtractedInsights {
  8→    let text = String::from_utf8_lossy(raw_output);
  9→    let mut dead_ends = Vec::new();
 10→    let mut decisions = Vec::new();
 11→
 12→    for line in text.lines() {
 13→        let trimmed = line.trim();
 14→        if trimmed.is_empty() || trimmed.len() < 10 {
 15→            continue;
 16→        }
 17→        let lower = trimmed.to_lowercase();
 18→
 19→        // Dead end patterns
 20→        if let Some(de) = try_extract_dead_end(&lower, trimmed) {
 21→            dead_ends.push(de);
 22→        }
 23→
 24→        // Decision patterns
 25→        if let Some(d) = try_extract_decision(&lower, trimmed) {
 26→            decisions.push(d);
 27→        }
 28→    }
 29→
 30→    // Deduplicate by approach/description
 31→    dead_ends.dedup_by(|a, b| a.approach == b.approach);
 32→    decisions.dedup_by(|a, b| a.description == b.description);
 33→
 34→    ExtractedInsights {
 35→        dead_ends,
 36→        decisions,
 37→    }
 38→}
 39→
 40→pub struct ExtractedInsights {
 41→    pub dead_ends: Vec<DeadEnd>,
 42→    pub decisions: Vec<Decision>,
 43→}
 44→
 45→fn try_extract_dead_end(lower: &str, original: &str) -> Option<DeadEnd> {
 46→    // Pattern: "tried X but Y"
 47→    if let Some(rest) = lower.strip_prefix("tried ") {
 48→        if let Some((approach, reason)) = rest.split_once(" but ") {
 49→            return Some(DeadEnd {
 50→                approach: approach.trim().to_string(),
 51→                reason: reason.trim().to_string(),
 52→            });
 53→        }
 54→    }
 55→
 56→    // Pattern: "rejected X because Y" or "rejected X: Y"
 57→    if let Some(rest) = lower.strip_prefix("rejected ") {
 58→        if let Some((approach, reason)) = rest
 59→            .split_once(" because ")
 60→            .or_else(|| rest.split_once(": "))
 61→        {
 62→            return Some(DeadEnd {
 63→                approach: approach.trim().to_string(),
 64→                reason: reason.trim().to_string(),
 65→            });
 66→        }
 67→    }
 68→
 69→    // Pattern: "X didn't work because Y"
 70→    if let Some(pos) = lower.find(" didn't work") {
 71→        let approach = &original[..pos];
 72→        let reason = lower
 73→            .get((pos + " didn't work".len())..)
 74→            .and_then(|r| r.strip_prefix(" because ").or(r.strip_prefix(": ")))
 75→            .unwrap_or("did not work as expected");
 76→        if !approach.is_empty() && approach.len() < 80 {
 77→            return Some(DeadEnd {
 78→                approach: approach.trim().to_string(),
 79→                reason: reason.trim().to_string(),
 80→            });
 81→        }
 82→    }
 83→
 84→    // Pattern: "instead of X" (looser, only if line is short enough to be a summary)
 85→    if lower.contains("instead of ") && original.len() < 120 {
 86→        if let Some(pos) = lower.find("instead of ") {
 87→            let approach = &original[(pos + "instead of ".len())..];
 88→            let reason = &original[..pos];
 89→            if !approach.is_empty() && approach.len() < 80 && !reason.is_empty() {
 90→                return Some(DeadEnd {
 91→                    approach: approach.trim().trim_end_matches('.').to_string(),
 92→                    reason: reason.trim().to_string(),
 93→                });
 94→            }
 95→        }
 96→    }
 97→
 98→    None
 99→}
100→
101→fn try_extract_decision(lower: &str, original: &str) -> Option<Decision> {
102→    // Pattern: "decided to X because Y"
103→    if let Some(rest) = lower.strip_prefix("decided to ") {
104→        if let Some((desc, rationale)) = rest.split_once(" because ") {
105→            return Some(Decision {
106→                description: desc.trim().to_string(),
107→                rationale: rationale.trim().to_string(),
108→            });
109→        }
110→    }
111→
112→    // Pattern: "chose X over Y" (short lines only)
113→    if lower.starts_with("chose ") && original.len() < 120 {
114→        if let Some((desc, _)) = lower
115→            .strip_prefix("chose ")
116→            .and_then(|r| r.split_once(" over "))
117→        {
118→            return Some(Decision {
119→                description: desc.trim().to_string(),
120→                rationale: original.to_string(),
121→            });
122→        }
123→    }
124→
125→    None
126→}
